def re_arrange(arr):
    positive = [x for x in arr if x >= 0]
    negative = [x for x in arr if x < 0]
    result = []

    while positive and negative:
        result.append(negative.pop())
        result.append(positive.pop())

    while positive:
        result.append(positive.pop())

    while negative:
        result.append(negative.pop())

    return result
